.bg{position:absolute;inset:0;background:linear-gradient(#12052e 0%,#3b0f63 55%,#c2306e 100%)}
.floor{position:absolute;left:-20%;right:-20%;bottom:-10%;height:46%;transform:perspective(500px) rotateX(62deg);
 background-image:linear-gradient(#ff5fd2 3px,transparent 3px),linear-gradient(90deg,#ff5fd2 3px,transparent 3px);background-size:120px 90px;opacity:.75}
.sun{position:absolute;right:8%;top:14%;width:420px;height:420px;border-radius:50%;background:linear-gradient(#ffe45c,#ff6a3d);
 -webkit-mask:repeating-linear-gradient(#000 0 34px,transparent 34px 44px);opacity:.9}
.box{position:absolute;left:5%;top:7%;width:600px;height:860px;overflow:hidden;transform:rotate(-4deg);box-shadow:0 30px 60px rgba(0,0,0,.6);border-radius:6px}
.box img{position:absolute;left:-645px;top:-62px;width:1920px}
.t{position:absolute;left:44%;right:4%;color:#fff;text-align:center}
h1{margin:0;font:italic 900 128px/0.95 "Liberation Sans";color:#ffe14a;-webkit-text-stroke:5px #1d0a52;text-shadow:8px 8px 0 #ff3d8b,16px 16px 0 #1d0a52;letter-spacing:-2px}
.free{top:52%;font:italic 900 92px "Liberation Sans";color:#fff;text-shadow:5px 5px 0 #1d0a52}
.url{top:72%;font:700 60px "Liberation Mono";background:#fff;color:#1d0a52;display:inline-block;left:50%;right:auto;padding:10px 34px;border:6px solid #1d0a52;box-shadow:10px 10px 0 #ff3d8b}
.tag{position:absolute;right:4%;bottom:4%;font:700 30px "Liberation Sans";color:#ffe14a;letter-spacing:4px}
.bar{position:absolute;left:44%;right:4%;top:47%;height:6px;background:#ff3d8b}

